    "COMPLETED": "All hypotheses evaluated; Apple stopped using the us-gaap Revenues concept after FY2018 and switched to the ASC 606 concept.",
    "REMAINING": "-",
    "DECISIONS": "H-c710de supported; H-b20b8d refuted; H-f3cf79 refuted; H-d7f2af refuted.",
    "CONTEXT": "Apple's revenue reporting changed after FY2018 due to ASC 606 adoption, not data loss or subsidiary-specific concepts."
  },
  "answer": {
    "summary": "Apple stopped reporting revenue under the legacy us-gaap Revenues concept after fiscal year 2018. Instead, it began reporting revenue under the ASC 606 concept RevenueFromContractWithCustomerExcludingAssessedTax starting in FY2019. The EDGAR pipeline is working, as shown by continued Revenues facts for IBM and Tesla after FY2018, and there are no zero or null Revenues facts for Apple after FY2018 that could mask data.",
    "claims": [
      {
        "text": "Apple has zero Revenues facts for fiscal years after 2018.",
        "evidence": ["E-b549e1"]
      },
      {
        "text": "Apple reports revenue under the ASC 606 concept 'RevenueFromContractWithCustomerExcludingAssessedTax' for fiscal years 2019 through 2024.",
        "evidence": ["E-f49a73"]
      },
      {
        "text": "IBM and Tesla have Revenues facts after FY2018, indicating the EDGAR pipeline is functional.",
        "evidence": ["E-dc2609"]
      },
      {
        "text": "There are no Revenues facts (including zero or null) for Apple after FY2018.",
        "evidence": ["E-e6c8da"]
      }
    ],
    "inferences": [
      {
        "text": "The shift from the Revenues concept to the ASC 606 concept reflects Apple's adoption of the new revenue recognition standard (ASC 606) effective FY2019.",
        "basis": ["Claim about ASC 606 concept usage after FY2018 (E-f49a73)"]
      }
    ],
    "hypothesis_verdicts": [
      {
        "id": "H-c710de",
        "status": "supported",
        "evidence": ["E-b549e1", "E-bdbb98", "E-f49a73"],
        "why": "Shows Apple has no Revenues facts after FY2018 but does report under the ASC 606 concept from FY2019 onward."
      },
      {
        "id": "H-b20b8d",
        "status": "refuted",
        "evidence": ["E-dc2609", "E-f49a73"],
        "why": "IBM and Tesla continue to have Revenues facts after FY2018, proving the pipeline works; Apple's lack of Revenues facts is not a pipeline issue."
      },
      {
        "id": "H-f3cf79",
        "status": "refuted",
        "evidence": ["E-e6c8da"],
        "why": "There are zero Revenues facts for Apple after FY2018, not merely zero/null values that could hide data."
      },
      {
        "id": "H-d7f2af",
        "status": "refuted",
        "evidence": ["E-cb7f4a"],
        "why": "After FY2018 Apple uses only the ASC 606 revenue concept, not subsidiary‑specific revenue concepts."
      }
    ]
  }
